vals={'__HERO__':scenes[0]['thumb'],'__CARDS__':cards,'__PLANS__':plans,'__RESEARCH__':md((O/'00_Research/RESEARCH_REPORT.md').read_text())+md((O/'00_Research/URBAN_ADDENDUM.md').read_text()),'__SOURCES__':sourcehtml,'__PAYLOAD__':payload}
for k,v in vals.items():template=template.replace(k,v,1)
dest=O.parent/'Persepolis_Single_File.html';dest.write_text(template)
print(json.dumps({'bytes':dest.stat().st_size,'sha256':hashlib.sha256(dest.read_bytes()).hexdigest(),'cards':len(scenes),'sources':len(sources)}))
